-- Deities and Demigods: D&D pantheon divine stat blocks, batch B.
-- Source: Deities and Demigods (2002), Chapter 3, pp. 66-73.
-- Printed 3.0 statistics are preserved, with official 3.5 revision deltas recorded separately in mechanics JSON.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Half-demon, half-boar mask' WHERE source_id='dd-3.0' AND slug='erythnul' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Disk bearing a curved line with an upturned crescent above' WHERE source_id='dd-3.0' AND slug='fharlanghn' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Nugget of gold' WHERE source_id='dd-3.0' AND slug='garl-glittergold' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Empty eye socket' WHERE source_id='dd-3.0' AND slug='gruumsh' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-erythnul','Erythnul Divine Stat Block','66-67',
 'Erythnul, the Many, is a divine-rank-15 intermediate deity of slaughter, panic, malice, and hatred whose combat power combines barbarian fury, martial skill, rogue precision, and sorcery.',
