0,"temporaryHitPoints":100},"armorClassPenalty":5,"notWindedAfterward":true}},"avatar":{"divineRank":7,"armorClass":57,"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":25},"saves":{"fort":50,"ref":50,"will":46},"spellLikeCasterLevel":17,"spellLikeSaveDc":"27 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","evil"],"damageReduction":"25/epic","fireResistance":20,"notes":"Use 3.5 barbarian, fighter, rogue, and sorcerer class features/skills while preserving divine rank and source class levels."}}'),

('dd-statblock-fharlanghn','Fharlanghn Divine Stat Block','67-69',
 'Fharlanghn, Dweller on the Horizon, is a divine-rank-14 intermediate deity of roads, horizons, distance, and travel.',
 '{"deitySlug":"fharlanghn","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":14,"titles":["Dweller on the Horizon"],"symbol":"Disk bearing a curved line with an upturned crescent above","homePlane":"Material Plane","alignment":"N","classes":[{"class":"Bard","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d6+180 bard + 20d8+180 cleric","hitPoints":980,"initiative":21,"alwaysFirst":true,"speed":{"land":60},"armorClass":{"total":79,"dexterity":17,"divine":14,"natural":27,"deflection":11},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"travelersFriend":"+5 defending quarterstaff +64/+59/+54/+49 and +5 speed quarterstaff +64/+64/+59","spellTouch":{"melee":61,"ranged":71}},"saves":{"fort":55,"ref":63,"will":53},"abilities":{"str":24,"dex":45,"con":28,"int":31,"wis":25,"cha":33},"specialQualities":{"printedDamageReduction":"49/+4","printedFireResistance":34,"spellResistance":46,"divineAura":{"radiusFeet":1400,"dc":35},"bardicKnowledge":30,"bardicMusicUsesPerDay":20},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Avatar","Divine Blast","Create Object","Create Greater Object","Divine Celerity","Divine Shield","Footsore","Gift of Life","Instant Move","Mass Divine Blast","Shape Path","Stride","Supreme Initiative"],"domainPowers":{"luckRerollsPerDay":14,"protectiveWardPerDay":14,"protectiveWardResistanceBonus":20,"travelFreedomOfMovementRoundsPerDay":20},"spellLikeAbilities":{"casterLevel":24,"saveDc":"35 + spell level"},"spellcasting":{"bardSpellsKnownPerDay":"4/7/7/7/6/6/6","bardBaseDc":"21 + spell level","clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"17 + spell level"},"uniqueAbilities":{"shapePath":{"concentrationMinutes":10,"baseAreaFeet":"140 x 140 x 10 deep","uses":["footpath","road","tunnel","bridge","clear natural blockages"],"affectsRock":true,"canTradeWidthForLength":true,"tooSlowToTrapCreatures":true}},"possessions":{"travelersFriend":"double weapon; both ends +5, one defending and one speed; caster level 20"},"avatar":{"divineRank":7,"armorClass":65,"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":28},"saves":{"fort":48,"ref":56,"will":45},"spellLikeCasterLevel":17,"spellLikeSaveDc":"28 + spell level"},"revision3_5":{"alignmentSubtypes":[],"damageReduction":"25/epic","fireResistance":19,"notes":"Use 3.5 bard and cleric class features/skill names; preserve divine rank and source levels."}}'),

('dd-statblock-garl-glittergold','Garl Glittergold Divine Stat Block','69-71',
 'Garl Glittergold, the greater deity of gnomes, combines illusion magic, clerical power, rogue talents, humor, craft, and protection.',
 '{"deitySlug":"garl-glittergold","pantheon":"dnd","sourceEdition":"3.0","rankBand":"greater","divineRank":18,"titles":["The Joker","The Watchful Protector","The Priceless Gem","The Sparkling Wit"],"symbol":"Nugget of gold","homePlane":"Bytopia","alignment":"NG","classes":[{"class":"Illusionist","level":12},{"class":"Cleric","level":14},{"class":"Rogue","level":16}],"creature":{"type":"Outsider","subtypes":["Good"],"size":"Small","hitDice":"20d8+160 outsider + 12d4+96 (printed label: Clr; class heading says Illusionist) + 14d8+112 cleric + 16d6+128 rogue","hitPoints":912,"initiative":16,"speed":{"land":50},"armorClass":{"total":84,"size":1,"dexterity":12,"divine":18,"natural":31,"deflection":12},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"battleaxe":"+72/+72/+67/+62/+57 melee, +5 ghost touch speed dancing battleaxe; greater deity always receives 20 on attack rolls","damage":"1d8+14/x3; greater deity always deals maximum damage (22)","spellTouch":{"melee":66,"ranged":72}},"saves":{"fort":59,"ref":63,"will":63,"greaterDeityAlways20":true},"abilities":{"str":22,"dex":34,"con":26,"int":42,"wis":30,"cha":34},"specialQualities":{"gnomeTraits":true,"printedDamageReduction":"53/+4","printedFireResistance":38,"spellResistance":70,"divineAura":{"radiusMiles":18,"dc":35},"sneakAttack":"+8d6 (48 maximum for greater deity)","rogueFeatures":["crippling strike","defensive roll","improved evasion","uncanny dodge","traps"],"familiar":"badgers"},"sourceAnomalies":{"hitDiceLabel":"The 12d4+96 line is printed as (Clr) even though the class heading is Illusionist 12/Cleric 14/Rogue 16; preserved rather than silently relabeled."},"salientDivineAbilitiesRetrievedForAvatar":["Arcane Mastery","Automatic Metamagic (quicken wizard spells)","Banestrike (kobolds)","Clearsight","Control Creatures (gnomes)","Divine Blast","Divine Dodge","Divine Glibness","Divine Shield","Divine Spell Focus (Illusion)","Spontaneous Wizard Spells"],"mainSalientAbilityListStatus":"The retrieved PDF text did not expose the complete main-block salient-ability line reliably; avatar subset is preserved without inventing omitted main-only abilities.","domainPowers":{"goodSpellsCasterLevelBonus":1,"protectionWardUsesPerDay":18,"trickeryDomain":true},"spellcasting":{"classes":["illusionist 12","cleric 14"],"illusionFocus":true,"avatarClericIllusionSaveDc":"29 + spell level","avatarWizardIllusionSaveDc":"34 + spell level"},"automaticActions":{"craftSkills":["gemcutting","metalworking","stoneworking","trapmaking"],"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":["magic gems","figurines of wondrous power","jeweled items such as helm of brilliance","any magic ring"],"avatar":{"divineRank":9,"armorClass":66,"damageReduction":"44/+4","fireResistance":29,"spellResistance":61,"divineAura":{"radiusFeet":900,"dc":26},"saves":{"fort":50,"ref":54,"will":52},"spellLikeCasterLevel":19,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"30/epic","fireResistance":23,"notes":"Use 3.5 rogue and specialist-wizard terminology. Preserve the source HD-label anomaly as metadata."}}'),

