 'Gruumsh One-Eye is a divine-rank-16 greater deity of orcs, territory, and war, combining fighter, cleric, and barbarian levels.',
 '{"deitySlug":"gruumsh","pantheon":"dnd","sourceEdition":"3.0","rankBand":"greater","divineRank":16,"titles":["One-Eye","He Who Never Sleeps"],"symbol":"Empty eye socket","homePlane":"Acheron","alignment":"CE","classes":[{"class":"Fighter","level":20},{"class":"Cleric","level":9},{"class":"Barbarian","level":9}],"creature":{"type":"Outsider","subtypes":["Chaotic","Evil","Orc"],"size":"Medium","hitDice":"20d8+220 outsider + 20d10+220 fighter + 9d8+99 cleric + 9d12+99 barbarian","hitPoints":1178,"initiative":11,"speed":{"armored":40,"base":70},"armorClass":{"total":78,"dexterityLimitedByArmor":1,"divine":16,"natural":29,"armor":13,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"bloodspear":"+83/+78/+73/+68 melee; 1d8+50/18-20/x3; greater deity always receives 20 on attacks and maximum damage 58","spellTouch":null},"saves":{"fort":60,"ref":54,"will":56,"greaterDeityAlways20":true},"abilities":{"str":46,"dex":25,"con":33,"int":24,"wis":25,"cha":29},"specialQualities":{"printedDamageReduction":"67/+5","printedFireImmunity":true,"spellResistance":48,"divineAura":{"radiusMiles":16,"dc":35},"rageUsesPerDay":3},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Annihilating Strike","Avatar","Banestrike (dwarves)","Banestrike (elves)","Battlesense","Control Creatures (orcs)","Divine Battle Mastery","Divine Blast","Divine Shield","Divine Weapon Focus (longspear)","Divine Weapon Specialization (longspear)","Extra Domain (Chaos)","Fog of War","Hand of Death","Increased Damage Reduction","Life and Death","Mass Divine Blast","Wound Enemy"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"evilSpellsCasterLevelBonus":1,"strengthUsesPerDay":16,"strengthEnhancementBonus":9},"spellLikeAbilities":{"casterLevel":28,"chaosAndEvilCasterLevel":29,"saveDc":"35 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/7/7/6/4/3","clericBaseDc":"17 + spell level"},"uniqueAbilities":{"fogOfWar":{"radiusFeet":30,"heightFeet":10,"saveDc":37,"basis":"cloudkill-like divine ability"}},"possessions":{"bloodspear":"+5 keen chaotic unholy spear whose length can vary; caster level 20"},"avatar":{"divineRank":8,"armorClass":62,"damageReduction":"43/+4","spellResistance":40,"divineAura":{"radiusFeet":800,"dc":27},"saves":{"fort":52,"ref":46,"will":46},"spellLikeCasterLevel":20,"spellLikeSaveDc":"27 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","evil"],"damageReduction":"30/epic","fireResistance":21,"printedFireImmunityReplacedByRankRule":true,"notes":"The official 3.5 deity update replaces rank-derived 3.0 fire protection with resistance 5 + divine rank unless another explicit ability grants more; the original printed fire immunity remains recorded above."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,d.description,0,NULL,1,
       'deity-statblock','statblock',0,1,'dd-dnd-pantheon',NULL,
       '["deities-and-demigods","deity","statblock","d&d-pantheon"]',d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
